def vectorLpPartitionAverage (hp : p ≠ ∞) (s : Set α) : Lp E p μ →L[𝕜] E :=
  (μ.real s : 𝕜)⁻¹ • ((finiteLpIntegral (𝕜 := 𝕜) (μ := μ.restrict s) hp).comp
    (P5Support.lebesgueLpRestrict (𝕜 := 𝕜) s))

