def vectorLpIndicator (s : Set α) (hs : MeasurableSet s) : E →L[𝕜] Lp E p μ :=
  (P5Support.lebesgueLpExtend (𝕜 := 𝕜) s hs).toContinuousLinearMap.comp
    (Lp.constL p (μ.restrict s) 𝕜)

